def find_nth_significant_digit_position(number_str, n):
    """
    Find the position of the nth significant digit in a number.

    Args:
        number_str (str): The number as a string
        n (int): The position of the significant digit to find (1-based indexing)

    Returns:
        dict: A dictionary containing:
            - position: The position of the nth significant digit (0-based indexing)
            - digit: The digit at that position
            - place_value: The place value (1, 0.1, 0.01, etc.)
    """
    # Clean the input string
    number_str = number_str.strip()
    for char in number_str:
        if not (char.isdigit() or char == '.' or char == '-'):
            number_str = number_str.split(char)[0].strip()
            break

    # Remove negative sign if present
    if number_str.startswith('-'):
        number_str = number_str[1:]

    # Split into whole and decimal parts
    if '.' in number_str:
        whole, decimal = number_str.split('.')
    else:
        whole, decimal = number_str, ''

    # Remove leading zeros in whole part
    whole = whole.lstrip('0')

    # Create a list of significant digits
    sig_digits = []

    if whole == '':
        # If no whole part, handle decimal part
        leading_zeros = 0
        for digit in decimal:
            if digit == '0' and not sig_digits:
                leading_zeros += 1
            else:
                sig_digits.append(digit)

        # Calculate place values
        if n <= len(sig_digits):
            return {
                'position': whole.find('.') + leading_zeros + n,
                'digit': sig_digits[n-1],
                'place_value': 10**(-leading_zeros-n)
            }
    else:
        # Handle whole part and decimal part
        for digit in whole:
            sig_digits.append(digit)

        for digit in decimal:
            sig_digits.append(digit)

        if n <= len(sig_digits):
            # Determine position and place value
            if n <= len(whole):
                # In the whole part
                position = n - 1
                place_value = 10**(len(whole) - n)
            else:
                # In the decimal part
                position = len(whole) + 1 + (n - len(whole) - 1)
                place_value = 10**(-1 * (n - len(whole)))

            return {
                'position': position,
                'digit': sig_digits[n-1],
                'place_value': place_value
            }

    # If n is greater than the number of significant digits
    return {
        'position': None,
        'digit': None,
        'place_value': None
    }

def check_next_digit(number_str, n):
    """
    Check the digit immediately following the nth significant digit to decide whether to round up or down.

    Args:
        number_str (str): The number as a string
        n (int): The position of the significant digit (1-based indexing)

    Returns:
        dict: A dictionary containing:
            - next_digit: The digit following the nth significant digit
            - round_up: Boolean indicating whether to round up (True) or down (False)
    """
    # Clean the input string
    number_str = number_str.strip()
    for char in number_str:
        if not (char.isdigit() or char == '.' or char == '-'):
            number_str = number_str.split(char)[0].strip()
            break

    # Remove negative sign if present
    negative = False
    if number_str.startswith('-'):
        number_str = number_str[1:]
        negative = True

    # Split into whole and decimal parts
    if '.' in number_str:
        whole, decimal = number_str.split('.')
    else:
        whole, decimal = number_str, ''

    # Remove leading zeros in whole part
    whole = whole.lstrip('0')

    # Create a list of significant digits
    sig_digits = []

    if whole == '':
        # If no whole part, handle decimal part
        leading_zeros = 0
        for digit in decimal:
            if digit == '0' and not sig_digits:
                leading_zeros += 1
            else:
                sig_digits.append(digit)
    else:
        # Handle whole part and decimal part
        for digit in whole:
            sig_digits.append(digit)

        for digit in decimal:
            sig_digits.append(digit)

    # Check if n is within range
    if n < len(sig_digits):
        next_digit = sig_digits[n]
        round_up = int(next_digit) >= 5
        return {
            'next_digit': next_digit,
            'round_up': round_up
        }
    else:
        # No digit after the nth significant digit
        return {
            'next_digit': '0',
            'round_up': False
        }

