def extract_vector_coefficients(vector_str):
    """
    Extract the coefficients of i, j, k from a vector expression.

    Args:
        vector_str (str): A string representation of a vector in the form of ai+bj+ck

    Returns:
        tuple: A tuple of three values representing the coefficients of i, j, k
    """
    # Initialize coefficients
    i_coef, j_coef, k_coef = 0, 0, 0

    # Remove all spaces and parentheses
    vector_str = vector_str.replace(' ', '').replace('(', '').replace(')', '')

    # Split by + or - signs, but keep the signs
    terms = []
    current_term = ""
    for char in vector_str:
        if char in ['+', '-'] and current_term:
            terms.append(current_term)
            current_term = char
        else:
            current_term += char
    if current_term:
        terms.append(current_term)

    # Process each term
    for term in terms:
        if 'i' in term:
            if term == 'i':
                i_coef = 1
            elif term == '-i':
                i_coef = -1
            else:
                i_coef = int(term.replace('i', ''))
        elif 'j' in term:
            if term == 'j':
                j_coef = 1
            elif term == '-j':
                j_coef = -1
            else:
                j_coef = int(term.replace('j', ''))
        elif 'k' in term:
            if term == 'k':
                k_coef = 1
            elif term == '-k':
                k_coef = -1
            else:
                k_coef = int(term.replace('k', ''))

    return (i_coef, j_coef, k_coef)

