import math

def exponential_cdf(lambda_param, t):
    """
    Calculate the cumulative distribution function (CDF) for exponential distribution.

    CDF = 1 - e^(-lambda * t) for t >= 0
    """
    if t < 0:
        return 0.0
    return 1.0 - math.exp(-lambda_param * t)

def calculate_cdf_x(x):
    """
    Calculate the cumulative distribution function (CDF) for the Pareto distribution of X.

    The PDF of X is f(x) = 2/x^3 for x > 1.
    The CDF is F(x) = ∫(1 to x) f(t) dt.
    """
    if x <= 1:
        return 0.0
    else:
        # F(x) = 1 - 1/x^2 for x > 1
        return 1.0 - 1.0/(x**2)

def construct_normal_approximation(population_mean, sample_mean_std):
    """
    Construct a normal distribution approximation

    According to the Central Limit Theorem, the sample mean approximately follows a normal distribution
    with mean equal to the population mean and standard deviation equal to the standard deviation of the sample mean
    """
    return {
        "mean": population_mean,
        "std": sample_mean_std
    }

def calculate_combinations(n, k):
    """Calculate the combination number C(n,k) = n! / (k! * (n-k)!)

    Calculate the number of different combinations of selecting k elements from n elements using the combination formula
    """
    from math import factorial
    return factorial(n) // (factorial(k) * factorial(n - k))

